      .grid = grid,
      .basis = *basis,
      .basis_avg = *basis_avg,
      .local = local,
      .local_avg = local_avg,
      .local_avg_ext = local_avg_ext,
      .weight = weight,
      .avg_dim = avg_dim,
      .use_gpu = use_gpu
    }
  );
